using System;using System.Diagnostics;using System.Runtime.InteropServices;
class Ra2RepairCostGateTest{[DllImport("kernel32.dll")]static extern IntPtr OpenProcess(uint a,bool b,int p);[DllImport("kernel32.dll")]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr r);[DllImport("kernel32.dll")]static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr w);static void Main(string[]x){bool off=x.Length==1&&x[0]=="--off";var g=Process.GetProcessesByName("game")[0];IntPtr h=OpenProcess(0x438,false,g.Id);IntPtr a=new IntPtr(0x0044BA9B);byte[]cur=new byte[6];IntPtr n;if(!ReadProcessMemory(h,a,cur,6,out n)){Console.WriteLine("READ_FAILED");return;}byte[]want=off?new byte[]{0x0F,0x85,0xF2,0x00,0x00,0x00}:new byte[]{0x90,0x90,0x90,0x90,0x90,0x90};if(!off&&(cur[0]!=0x0F||cur[1]!=0x85)){Console.WriteLine("PATCH_MISMATCH");return;}if(off&&(cur[0]!=0x90||cur[1]!=0x90)){Console.WriteLine("NOT_PATCHED");return;}IntPtr w;if(WriteProcessMemory(h,a,want,6,out w)&&w.ToInt64()==6)Console.WriteLine("REPAIR_COST_GATE_{0}",off?"RESTORED":"BYPASSED");else Console.WriteLine("WRITE_FAILED");}}
